        Stage.objects.create(
            skill=skill,
            index=0,
            url_pattern=path,
            page_kind=skill.page_kind or "",
            playbook=skill.playbook or [],
            demonstration=skill.demonstration or [],
            memory_keys=skill.memory_keys or [],
            vault_file_ids=[],
            exit="",
        )


